import java.util.Scanner;

public class Main {
    static long fastExp(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        final long MOD = 1000000007;
        while (scanner.hasNextLong()) {
            long p = scanner.nextLong();
            long k = scanner.nextLong();

            if (k == 0) {
                System.out.println(fastExp(p, p - 1, MOD));
                continue;
            }
            if (k == 1) {
                System.out.println(fastExp(p, p, MOD));
                continue;
            }

            long cycle_length = 0;
            long val = 1;
            long next_val = -1;
            do {
                next_val = (k * val) % p;
                val = next_val;
                cycle_length++;
            } while (next_val != 1);

            System.out.println(fastExp(p, (p - 1) / cycle_length, MOD));
        }
        scanner.close();
    }
}
